-- 견적문의 데이터 삽입
INSERT INTO board_quote (title, content, writer, password, company, email, phone, is_answered, created_at) VALUES
-- 답변대기 견적
('H형강 200*200 100톤 견적 요청', '안녕하세요.\n\nH형강 200*200*8*12 규격으로 100톤 구매 예정입니다.\n\n납기: 2월 중순\n납품장소: 충남 천안시\n\n견적서 부탁드립니다.', '이건우', 'quote123', '대한건설', 'lee@daehan.co.kr', '010-2345-6789', 0, '2025-01-28 14:30:00'),
('철근 D16, D19 대량 구매 문의', '철근 구매 견적 요청드립니다.\n\n- D16: 80톤\n- D19: 120톤\n\n현장: 세종시 건설현장\n납기: 3월 초\n\n빠른 답변 부탁드립니다.', '박민수', 'quote123', '세종건설', 'park@sejong.co.kr', '010-3456-7890', 0, '2025-01-27 11:20:00'),
('철판 및 형강류 견적 요청', '다음 자재 견적 부탁드립니다.\n\n1. 철판 6T: 50장\n2. 철판 9T: 30장\n3. ㄱ형강 50*50*6: 200개\n4. ㄷ형강 100*50*5: 150개\n\n부가세 포함 견적 요청합니다.', '김영호', 'quote123', '영호산업', 'kim@youngho.co.kr', '010-4567-8901', 0, '2025-01-26 16:45:00'),
('각종 파이프류 단가 문의', '파이프 단가 문의드립니다.\n\n- KS파이프 100A: 100본\n- 사각파이프 50*50*2.3: 200본\n- 환봉 25mm: 50본\n\n현금 결제 예정이며 자가 운송합니다.', '최준혁', 'quote123', '준혁무역', 'choi@junhyuk.co.kr', '010-5678-9012', 0, '2025-01-25 09:15:00'),
('메탈라스 대량 구매 건', '메탈라스 구매 문의입니다.\n\n규격: 0.5T\n수량: 1,000장\n\n창고 보관 가능한지도 함께 문의드립니다.', '정수진', 'quote123', '수진건축', 'jung@soojin.co.kr', '010-6789-0123', 0, '2025-01-24 13:00:00'),
('C형강 특수 규격 제작 가능 여부', 'C형강 특수 규격 제작 가능한지 문의드립니다.\n\n규격: 200*75*20*3.2\n수량: 500개\n\n제작 가능 시 납기와 단가 알려주세요.', '한상민', 'quote123', '상민엔지니어링', 'han@sangmin.co.kr', '010-7890-1234', 0, '2025-01-23 10:30:00'),
('데크플레이트 시공 포함 견적', '데크플레이트 자재 및 시공 견적 요청합니다.\n\n면적: 500평\n위치: 천안시 서북구\n공사기간: 2월 말\n\n현장 방문 가능하신지요?', '신동욱', 'quote123', '동욱종합건설', 'shin@dongwook.co.kr', '010-8901-2345', 0, '2025-01-22 15:20:00'),
('스테인리스 강관 견적 요청', '스테인리스 강관 견적 부탁드립니다.\n\nSUS304 50A: 50본\nSUS304 80A: 30본\n\n식품공장용이라 위생등급 필요합니다.', '임재현', 'quote123', '재현식품', 'lim@jaehyun.co.kr', '010-9012-3456', 0, '2025-01-21 11:00:00'),
('강널말뚝 임대 문의', '강널말뚝 임대 가능한지 문의드립니다.\n\n규격: 400*150*13\n수량: 200매\n기간: 6개월\n\n임대료와 운송비 포함 견적 부탁드립니다.', '윤성호', 'quote123', '성호토건', 'yoon@sungho.co.kr', '010-0123-4567', 0, '2025-01-20 14:15:00'),
('평철 및 환봉 소량 구매', '소량 구매 가능한지 문의드립니다.\n\n평철 50*6: 20개\n환봉 20mm: 10개\n\n개인 공방 운영 중입니다.', '조민정', 'quote123', '민정공방', 'jo@minjeong.co.kr', '010-1234-5678', 0, '2025-01-19 09:45:00'),
('H빔 긴급 구매 요청', 'H빔 긴급히 필요합니다.\n\nH-300*300*10*15: 20톤\n\n내일 오전 중 납품 가능한지요?\n추가 운송비 지불 가능합니다.', '강태우', 'quote123', '태우건설', 'kang@taewoo.co.kr', '010-2345-6789', 0, '2025-01-18 16:50:00'),
('앵글 및 찬넬 정기 공급 계약', '월 정기 공급 계약 문의입니다.\n\n월간 예상 물량:\n- 앵글 50*50*6: 50톤\n- 찬넬 100*50*5: 30톤\n\n장기계약 시 할인 가능한지요?', '서지훈', 'quote123', '지훈철강', 'seo@jihoon.co.kr', '010-3456-7890', 0, '2025-01-17 10:20:00'),
('특수강 가공 문의', '특수강 절단 가공 가능한지 문의드립니다.\n\nSM45C 환봉 100mm\n길이: 500mm로 절단\n수량: 100개\n\n가공비 포함 견적 부탁드립니다.', '홍길동', 'quote123', '길동정밀', 'hong@gildong.co.kr', '010-4567-8901', 0, '2025-01-16 13:30:00'),

-- 답변완료 견적
('[답변완료] 철근 D10~D25 종합 견적', '철근 각 규격별 100톤씩 견적 요청드렸습니다.\n\nD10, D13, D16, D19, D22, D25 각 100톤\n\n답변 감사합니다. 검토 후 연락드리겠습니다.', '김철수', 'quote123', '철수건설', 'kim@chulsoo.co.kr', '010-1111-2222', 1, '2025-01-15 09:00:00'),
('[답변완료] H형강 전 규격 단가표 요청', '견적 감사합니다.\n\n추가로 다른 규격도 필요한데 전체 단가표 받을 수 있을까요?', '이영희', 'quote123', '영희산업', 'lee@younghee.co.kr', '010-2222-3333', 1, '2025-01-14 14:20:00'),
('[답변완료] 철판 재고 문의', '6T, 9T, 12T 철판 재고 보유 현황 문의드렸습니다.\n\n빠른 답변 감사합니다.', '박준호', 'quote123', '준호철강', 'park@junho.co.kr', '010-3333-4444', 1, '2025-01-13 11:15:00'),
('[답변완료] 사각파이프 대량 구매', '사각파이프 각종 규격 대량 구매 건으로 문의드렸습니다.\n\n견적서 잘 받았습니다.', '최민수', 'quote123', '민수무역', 'choi@minsoo.co.kr', '010-4444-5555', 1, '2025-01-12 15:40:00'),
('[답변완료] 앵글 소량 구매 가능 여부', '소량 구매도 가능하다고 답변 주셔서 감사합니다.\n\n방문 구매하겠습니다.', '정하나', 'quote123', '하나공방', 'jung@hana.co.kr', '010-5555-6666', 1, '2025-01-11 10:30:00'),
('[답변완료] 스테인리스 봉강 견적', 'SUS304, SUS316 봉강 견적 잘 받았습니다.\n\n내부 검토 후 주문하겠습니다.', '강민준', 'quote123', '민준스틸', 'kang@minjun.co.kr', '010-6666-7777', 1, '2025-01-10 13:50:00'),
('[답변완료] C형강 규격 확인', '보유 규격 리스트 감사합니다.\n\n필요한 규격 확인되어 주문 예정입니다.', '신서연', 'quote123', '서연건설', 'shin@seoyeon.co.kr', '010-7777-8888', 1, '2025-01-09 09:25:00'),
('[답변완료] 철근 가공 문의', '철근 절곡 가공 가능하다고 답변 주셨네요.\n\n도면 보내드리겠습니다.', '임도윤', 'quote123', '도윤엔지니어링', 'lim@doyoon.co.kr', '010-8888-9999', 1, '2025-01-08 16:10:00'),
('[답변완료] 형강류 운송 문의', '운송비 포함 견적 감사합니다.\n\n배송 일정 조율하겠습니다.', '윤서준', 'quote123', '서준물류', 'yoon@seojun.co.kr', '010-9999-0000', 1, '2025-01-07 11:45:00'),
('[답변완료] 메탈라스 시공 견적', '자재 및 시공 견적 확인했습니다.\n\n계약서 작성 진행하겠습니다.', '조예준', 'quote123', '예준건축', 'jo@yejun.co.kr', '010-0000-1111', 1, '2025-01-06 14:35:00'),
('[답변완료] 평철 절단 가공', '평철 절단 가공비 확인했습니다.\n\n합리적인 가격이네요. 주문하겠습니다.', '한시우', 'quote123', '시우정밀', 'han@siwoo.co.kr', '010-1111-0000', 1, '2025-01-05 10:05:00'),
('[답변완료] 강관 파이프 정기 공급', '월 정기 공급 조건 검토했습니다.\n\n계약 진행하도록 하겠습니다.', '서주원', 'quote123', '주원산업', 'seo@juwon.co.kr', '010-2222-1111', 1, '2025-01-04 15:55:00'),
('[답변완료] 철판 가공 및 절단', '레이저 절단 가공 견적 받았습니다.\n\n도면 전달드리겠습니다.', '홍지호', 'quote123', '지호테크', 'hong@jiho.co.kr', '010-3333-2222', 1, '2025-01-03 09:40:00'),
('[답변완료] H빔 보 부재 견적', '구조 계산서 기준 견적 감사합니다.\n\n발주 진행하겠습니다.', '김건우', 'quote123', '건우구조', 'kim@gunwoo.co.kr', '010-4444-3333', 1, '2025-01-02 13:20:00'),
('[답변완료] 데크플레이트 자재 견적', '데크플레이트 견적 확인했습니다.\n\n현장 실측 후 정확한 수량 주문하겠습니다.', '이민혁', 'quote123', '민혁건설', 'lee@minhyuk.co.kr', '010-5555-4444', 1, '2025-01-01 11:10:00'),
('[답변완료] 특수 규격 제작 문의', '특수 규격 제작 가능 여부 답변 감사합니다.\n\n최소 주문 수량 확인 후 주문하겠습니다.', '박성준', 'quote123', '성준특수강', 'park@sungjun.co.kr', '010-6666-5555', 1, '2024-12-31 16:25:00'),
('[답변완료] 철강 자재 종합 견적', '종합 견적서 잘 받았습니다.\n\n프로젝트 확정되면 연락드리겠습니다.', '최지우', 'quote123', '지우종합건설', 'choi@jiwoo.co.kr', '010-7777-6666', 1, '2024-12-30 10:50:00');